using clock = std::chrono::steady_clock;
auto prev = clock::now();
const auto dt = std::chrono::microseconds(16'667);
auto lag = clock::duration::zero();
for (;;) {
    const auto now = clock::now();
    lag += now - prev; prev = now;
    lag = std::min(lag, std::chrono::milliseconds(250));   // clamp
    drainInput();
    while (lag >= dt) { step(dt); lag -= dt; }
    render(std::chrono::duration<double>(lag) / std::chrono::duration<double>(dt));
    std::this_thread::sleep_until(now + dt);               // coarse; re-measured above
}

